package com.sanctuarygames.createtransit;
import com.sanctuarygames.createtransit.radio.*;import com.sanctuarygames.createtransit.elevator.model.*;import net.minecraft.core.*;import net.minecraft.gametest.framework.*;import net.neoforged.neoforge.gametest.*;import net.minecraft.nbt.CompoundTag;
@GameTestHolder("createtransit") @PrefixGameTestTemplate(false)
public final class SpeakerUpdateGameTests {
 private static void check(boolean b,String m){if(!b)throw new GameTestAssertException(m);}
 @GameTest(template="elevator2_shaft",batch="speaker_update",timeoutTicks=40) public static void groups_persist_and_keep_local_coverage(GameTestHelper h){var l=h.getLevel();var data=new RadioStations();var local=new RadioSettings();local.enabled=true;local.volume=.7;local.radius=24;local.reverb=true;local.reverbRadius=160;local.reverbLevel=.2;var group=data.group("Central",local);group.station=data.add("Test","https://example.invalid/live.mp3");group.mode="POWERED";group.volume=.5;var effective=data.effective("Central",local);check(effective.radius==24&&effective.reverbRadius==160&&effective.volume==.35&&effective.station.equals(group.station),"Shared station and gain with local acoustic overrides");check(data.effective("Separate",local).station.isBlank(),"Separate group isolation");var t=data.save(new CompoundTag(),l.registryAccess());check(t.getList("Groups",10).size()==1,"Groups persisted in world data; reading an unknown group does not create it");try{var loader=RadioStations.class.getDeclaredMethod("load",CompoundTag.class,net.minecraft.core.HolderLookup.Provider.class);loader.setAccessible(true);var restored=(RadioStations)loader.invoke(null,t,l.registryAccess());check(restored.effective("Central",local).station.equals(group.station)&&restored.effective("Central",local).volume==.35,"Group data reload retains station and master volume");}catch(ReflectiveOperationException ex){throw new GameTestAssertException(ex.toString());}var copy=new RadioSettings();copy.load(effective.save());check(copy.reverb&&copy.reverbRadius==160&&copy.reverbLevel==.2,"Acoustics survive NBT");h.succeed();}
 @GameTest(template="elevator2_shaft",batch="speaker_update",timeoutTicks=40) public static void speaker_variants_mount_downward_and_save_dyes(GameTestHelper h){int index=0;for(var block:java.util.List.of(RadioRegistry.SPEAKER,RadioRegistry.CEILING,RadioRegistry.COLUMN,RadioRegistry.HORN)){var p=h.absolutePos(new BlockPos(3+index++,3,3));var s=block.get().defaultBlockState().setValue(StationSpeakerBlock.FACING,Direction.DOWN);h.getLevel().setBlock(p,s,3);var box=s.getShape(h.getLevel(),p).bounds();check(box.maxY==1&&box.minY>.4,"Ceiling mount touches top support and faces down");var e=(StationSpeakerEntity)h.getLevel().getBlockEntity(p);e.primary=1;e.secondary=5;e.group="Central";var copy=new StationSpeakerEntity(p,s);copy.loadWithComponents(e.saveWithoutMetadata(h.getLevel().registryAccess()),h.getLevel().registryAccess());check(copy.primary==1&&copy.secondary==5&&copy.group.equals("Central"),"Dyes/group persist on every registered variant");}var player=net.neoforged.neoforge.common.util.FakePlayerFactory.getMinecraft(h.getLevel());player.getAbilities().mayBuild=true;player.setShiftKeyDown(false);var origin=h.absolutePos(new BlockPos(3,3,3));var dye=new net.minecraft.world.item.ItemStack(net.minecraft.world.item.Items.BLUE_DYE);check(com.sanctuarygames.createtransit.block.ConnectedAccentDye.apply(h.getLevel(),origin,player,dye,Direction.UP)==4,"Connected primary dye reaches all four speaker variants");player.setShiftKeyDown(true);check(com.sanctuarygames.createtransit.block.ConnectedAccentDye.apply(h.getLevel(),origin,player,new net.minecraft.world.item.ItemStack(net.minecraft.world.item.Items.WHITE_DYE),Direction.UP)==4,"Connected secondary dye reaches all four speaker variants");player.setShiftKeyDown(false);for(int i=0;i<4;i++){var e=(StationSpeakerEntity)h.getLevel().getBlockEntity(origin.east(i));check(e.primary==11&&e.secondary==0,"Connected dyes preserve separate casing and grille colors");}h.succeed();}
 @GameTest(template="elevator2_shaft",batch="speaker_update",timeoutTicks=40) public static void voxel_cylinders_share_axis_aligned_mesh_and_collision(GameTestHelper h){for(int size=2;size<=5;size++){var props=CabinConfiguration.defaults(size,CabinConfiguration.Variant.CYLINDRICAL).save();props.setProperty("voxelCurve","true");props.setProperty("compact","true");props.setProperty("curvedGlass","true");var c=CabinConfiguration.load(props);check(c.voxelCurve()&&CabinConfiguration.load(c.save()).equals(c),"Voxel option persists");for(var f:CabinGeometry.body(c)){var a=f.a();var b=f.b();var d=f.c();double nx=(b.y()-a.y())*(d.z()-a.z())-(b.z()-a.z())*(d.y()-a.y()),ny=(b.z()-a.z())*(d.x()-a.x())-(b.x()-a.x())*(d.z()-a.z()),nz=(b.x()-a.x())*(d.y()-a.y())-(b.y()-a.y())*(d.x()-a.x());check((Math.abs(nx)>1e-8?1:0)+(Math.abs(ny)>1e-8?1:0)+(Math.abs(nz)>1e-8?1:0)<=1,"Every voxel face is axis aligned");}for(var box:CabinGeometry.collision(c,0,0))check(box.x0()>=0&&box.x1()<=size&&box.z0()>=0&&box.z1()<=size&&box.y1()<=2.5,"Voxel cabin remains in footprint");}h.succeed();}
}
